   <div id="app"></div>
   <script>
     const options = [
       { id: "notification-email", value: "Email", label: "Email" },
       { id: "notification-sms", value: "SMS", label: "SMS" },
       { id: "notification-push", value: "Push Notifications", label: "Push Notifications" }
     ];

     function RadioOption(option) {
       return `
         <div class="radio-option">
           <input
             id="${option.id}"
             type="radio"
             name="notificationPreference"
             value="${option.value}"
             required
           >
           <label for="${option.id}">${option.label}</label>
         </div>
       `;
     }

     function NotificationPreferenceField() {
       return `
         <div class="form-field">
           <fieldset aria-describedby="notification-help">
             <legend>
               How do you prefer to receive notifications?
               <span class="required-mark" aria-hidden="true">*</span>
             </legend>
             <p class="help-text" id="notification-help">Choose one option before submitting the form.</p>
             <div class="radio-list">
               ${options.map(RadioOption).join("")}
             </div>
           </fieldset>
         </div>
       `;
     }

     function SubmitButton() {
       return '<button class="submit-button" type="submit">Save preference</button>';
     }

     function FormSection() {
       return `
         <section aria-labelledby="preferences-title">
           <h1 id="preferences-title">Notification preferences</h1>
           <p class="intro">Set the channel you want us to use when sending updates and alerts.</p>
           <form id="preferences-form">
             ${NotificationPreferenceField()}
             ${SubmitButton()}
             <p class="status-message" id="form-status" aria-live="polite"></p>
           </form>
         </section>
       `;
     }

     function App() {
       return `
         <a class="skip-link" href="#main-content">Skip to main content</a>
         <div class="page-shell">
           <main id="main-content" class="card">
             ${FormSection()}
           </main>
         </div>
       `;
     }

     document.getElementById("app").innerHTML = App();

     const form = document.getElementById("preferences-form");
     const status = document.getElementById("form-status");

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       if (!form.reportValidity()) {
         return;
       }

       const selected = new FormData(form).get("notificationPreference");
       status.textContent = `Preference saved: ${selected}.`;
     });
   </script>
 </body>
